import pyomo.environ as pyo

DATA = {
    "foods": ["chicken", "rice", "broccoli", "tofu", "beans"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "chicken": 4,
        "rice": 8,
        "broccoli": 7,
        "tofu": 10,
        "beans": 1,
    },
    "content": {
        "protein": {
            "chicken": 18,
            "rice": 12,
            "broccoli": 13,
            "tofu": 5,
            "beans": 10,
        },
        "carbs": {
            "chicken": 6,
            "rice": 28,
            "broccoli": 19,
            "tofu": 16,
            "beans": 20,
        },
        "calories": {
            "chicken": 142,
            "rice": 88,
            "broccoli": 137,
            "tofu": 141,
            "beans": 150,
        },
    },
    "requirement": {
        "protein": 56,
        "carbs": 194,
        "calories": 2012,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.amount = pyo.Var(model.I, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][i] * m.amount[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.amount[i] for i in m.I) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


